1	/* ============================================================
2	   SCOPE HERO — scope-hero.module.css
3	   Matches: .work-banner.transparent-bg.scope-ban
4	   ============================================================ */
5	
6	.section {
7	  background-color: transparent;
8	  background-image: none;
9	  padding-top: 4rem;
10	  padding-bottom: 0;
11	  font-weight: 400;
12	  text-decoration: none;
13	  display: block;
14	}
15	
16	.container {
17	  max-width: 80rem;
18	  margin-left: auto;
19	  margin-right: auto;
20	  padding-left: 2rem;
21	  padding-right: 2rem;
22	  font-weight: 400;
23	  text-decoration: none;
24	}
25	
26	.inner {
27	  text-align: center;
28	  color: #05bafe;
29	  max-width: 70rem;
30	  margin-left: auto;
31	  margin-right: auto;
32	  padding: 0;
33	  font-weight: 400;
34	  text-decoration: none;
35	}
36	
37	/* ── Badge ── */
38	.badgeRow {
39	  grid-column-gap: 10px;
40	  grid-row-gap: 10px;
41	  justify-content: center;
42	  align-items: center;
43	  display: flex;
44	  margin-bottom: 0;
45	}
46	
47	.badge {
48	  color: #05bafe;
49	  background-color: #21cfff12;
50	  border: 1px solid #05bafe;
51	  border-radius: 20px;
52	  margin-bottom: 17px;
53	  padding: 0 13px;
54	  line-height: 14px;
55	  display: inline-flex;
56	  align-items: center;
57	}
58	
59	.badgeText {
60	  font-size: 12px;
61	  font-family: 'Roobert PRO', Arial, sans-serif;
62	  font-weight: 700;
63	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
64	  -webkit-background-clip: text;
65	  -webkit-text-fill-color: transparent;
66	  background-clip: text;
67	  padding-top: 6px;
68	  padding-bottom: 6px;
69	  margin: 0;
70	}
71	
72	/* ── H1 ── */
73	.heading {
74	  color: #092245;
75	  margin-top: 0;
76	  padding: 0;
77	  font-family: 'Roobert PRO', Arial, sans-serif;
78	  font-size: 40px;
79	  font-weight: 700;
80	  line-height: 1.25;
81	  text-decoration: none;
82	}
83	
84	/* ── Subtitle ── */
85	.subtitle {
86	  color: #2b2b2b;
87	  max-width: 536px;
88	  margin-left: auto;
89	  margin-right: auto;
90	  margin-top: 0;
91	  padding-left: 1.5rem;
92	  padding-right: 1.5rem;
93	  font-family: 'Roobert PRO', Arial, sans-serif;
94	  font-size: 16px;
95	  font-weight: 400;
96	  line-height: 28px;
97	  text-decoration: none;
98	}
99	
100	/* ── Badge grid wrapper ── */
101	.badgeGridWrap {
102	  justify-content: center;
103	  align-items: center;
104	  margin-top: 2rem;
105	  padding-left: 0;
106	  padding-right: 0;
107	  font-weight: 400;
108	  text-decoration: none;
109	  display: flex;
110	}
111	
112	/* ── Badge grid ── */
113	.badgeGrid {
114	  grid-column-gap: 16px;
115	  grid-row-gap: 16px;
116	  flex: 0 auto;
117	  width: auto;
118	  display: flex;
119	}
120	
121	/* ── Individual badge box ── */
122	.badgeBox {
123	  grid-column-gap: 10px;
124	  grid-row-gap: 10px;
125	  background-color: #fff;
126	  border-radius: 10px;
127	  align-items: center;
128	  width: auto;
129	  padding: 20px;
130	  transition: all 0.5s;
131	  display: flex;
132	  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
133	}
134	
135	.badgeIcon {
136	  width: 24px;
137	  height: 24px;
138	  flex-shrink: 0;
139	}
140	
141	.badgeText2 {
142	  color: #082753;
143	  text-align: left;
144	  margin-bottom: 0;
145	  font-family: 'Roobert PRO', Arial, sans-serif;
146	  font-size: 15px;
147	  font-weight: 500;
148	  line-height: 1.3;
149	}
150	
151	/* ============================================================
152	   min-width: 1280px
153	   ============================================================ */
154	@media screen and (min-width: 1280px) {
155	  .heading {
156	    color: #092245;
157	    font-size: 40px;
158	    line-height: 1.25;
159	  }
160	
161	  .subtitle {
162	    color: #2b2b2b;
163	    margin-top: 10px;
164	  }
165	}
166	
167	/* ============================================================
168	   min-width: 1440px
169	   ============================================================ */
170	@media screen and (min-width: 1440px) {
171	  .subtitle {
172	    margin-top: 10px;
173	  }
174	}
175	
176	/* ============================================================
177	   max-width: 991px
178	   ============================================================ */
179	@media screen and (max-width: 991px) {
180	  .heading {
181	    color: #092245;
182	    font-size: 40px;
183	    line-height: 1.25;
184	  }
185	
186	  .subtitle {
187	    margin-top: 10px;
188	  }
189	
190	  .container {
191	    padding-left: 2rem;
192	    padding-right: 2rem;
193	  }
194	}
195	
196	/* ============================================================
197	   max-width: 767px
198	   ============================================================ */
199	@media screen and (max-width: 767px) {
200	  .heading {
201	    font-size: 2.5rem;
202	    line-height: 1.25;
203	    margin-bottom: 10px;
204	  }
205	
206	  .subtitle {
207	    font-size: 1.1rem;
208	  }
209	
210	  .container {
211	    padding-left: 1.5rem;
212	    padding-right: 1.5rem;
213	  }
214	
215	  .badgeGrid {
216	    grid-column-gap: 15px;
217	    grid-row-gap: 15px;
218	    grid-template-columns: 1fr 1fr;
219	    display: grid;
220	    width: 100%;
221	  }
222	
223	  .badgeBox {
224	    padding-left: 20px;
225	    padding-right: 20px;
226	    width: 100%;
227	  }
228	}
229	
230	/* ============================================================
231	   max-width: 479px  (mobile)
232	   ============================================================ */
233	@media screen and (max-width: 479px) {
234	  .section {
235	    padding-top: 3rem;
236	    padding-bottom: 2rem;
237	  }
238	
239	  .container {
240	    padding-left: 1rem;
241	    padding-right: 1rem;
242	  }
243	
244	  .heading {
245	    font-size: 1.9rem;
246	    line-height: 1.25;
247	  }
248	
249	  .subtitle {
250	    text-align: center;
251	    padding-left: 0;
252	    padding-right: 0;
253	    font-size: 1rem;
254	  }
255	
256	  .badgeGrid {
257	    grid-template-columns: 1fr 1fr;
258	    display: grid;
259	    width: 100%;
260	  }
261	
262	  .badgeBox {
263	    flex-flow: column;
264	    width: 100%;
265	    align-items: center;
266	  }
267	
268	  .badgeText2 {
269	    text-align: center;
270	    font-size: 1rem;
271	    line-height: 16px;
272	  }
273	}
