1	/* ============================================================
2	   AGENCY FIT — agency-fit.module.css
3	   Matches: .how-work-sec2.overflow-hidden on how-it-works.html
4	   ============================================================ */
5	
6	.section {
7	  background-color: transparent;
8	  padding: 0 5% 70px;
9	  position: relative;
10	  overflow: hidden;
11	}
12	
13	.container {
14	  width: 100%;
15	  max-width: 1280px;
16	  margin-left: auto;
17	  margin-right: auto;
18	}
19	
20	/* Header (.demo-sec2-outer > .demo-cont-center > .column-regular.column-left.web-max) */
21	.header {
22	  text-align: center;
23	  max-width: 680px;
24	  margin-left: auto;
25	  margin-right: auto;
26	  margin-bottom: 40px;
27	}
28	
29	.heading {
30	  color: #092245;
31	  font-family: 'Roobert PRO', Arial, sans-serif;
32	  font-size: 40px;
33	  font-weight: 700;
34	  line-height: 48px;
35	  margin-top: 0;
36	  margin-bottom: 16px;
37	}
38	
39	.subtitle {
40	  color: #2b2b2b;
41	  text-align: center;
42	  font-family: 'Roobert PRO', Arial, sans-serif;
43	  font-size: 16px;
44	  font-weight: 400;
45	  line-height: 28px;
46	  margin: 0;
47	}
48	
49	/* Cards grid (.how-works-gridboxes) */
50	.grid {
51	  display: grid;
52	  grid-column-gap: 20px;
53	  grid-row-gap: 20px;
54	  grid-template-rows: auto;
55	  grid-template-columns: 1fr 1fr 1fr;
56	}
57	
58	/* Individual card (.demodev-sec2-grid-inner) */
59	.card {
60	  background-color: #def4ff;
61	  border: 1px solid #009ce0;
62	  border-radius: 20px;
63	  flex-flow: column;
64	  justify-content: flex-start;
65	  align-items: flex-start;
66	  padding: 22px;
67	  display: flex;
68	  position: relative;
69	}
70	
71	/* Icon (.demo2-icon) */
72	.cardIcon {
73	  display: block;
74	  margin-bottom: 12px;
75	}
76	
77	.cardTitle {
78	  color: #082753;
79	  font-family: 'Roobert PRO', Arial, sans-serif;
80	  font-size: 18px;
81	  font-weight: 700;
82	  line-height: 25px;
83	  margin-top: 0;
84	  margin-bottom: 7px;
85	  text-align: left;
86	}
87	
88	.cardText {
89	  color: #2b2b2b;
90	  text-align: left;
91	  font-family: 'Roobert PRO', Arial, sans-serif;
92	  font-size: 16px;
93	  font-weight: 400;
94	  line-height: 28px;
95	  margin: 0;
96	}
97	
98	/* ============================================================
99	   min-width: 1280px
100	   ============================================================ */
101	@media screen and (min-width: 1280px) {
102	  .section {
103	    padding-bottom: 70px;
104	  }
105	}
106	
107	/* ============================================================
108	   min-width: 1440px
109	   ============================================================ */
110	@media screen and (min-width: 1440px) {
111	  .section {
112	    padding-bottom: 70px;
113	  }
114	}
115	
116	/* ============================================================
117	   max-width: 991px
118	   ============================================================ */
119	@media screen and (max-width: 991px) {
120	  .section {
121	    padding-bottom: 60px;
122	  }
123	}
124	
125	/* ============================================================
126	   max-width: 767px
127	   ============================================================ */
128	@media screen and (max-width: 767px) {
129	  .grid {
130	    grid-template-columns: 1fr;
131	  }
132	}
133	
134	/* ============================================================
135	   max-width: 479px  (mobile)
136	   ============================================================ */
137	@media screen and (max-width: 479px) {
138	  .section {
139	    padding-top: 0;
140	    padding-bottom: 60px;
141	  }
142	
143	  .heading {
144	    font-size: 1.5rem;
145	    line-height: 1.3;
146	  }
147	
148	  .subtitle {
149	    font-size: 0.9375rem;
150	  }
151	
152	  .grid {
153	    grid-template-columns: 1fr;
154	  }
155	}
