1	/* ============================================================
2	   HOW WORKS STEPS (navy section) — how-works-steps.module.css
3	   Mirrors the existing how-it-works.module.css patterns
4	   ============================================================ */
5	
6	.section {
7	  -webkit-text-fill-color: inherit;
8	  background-color: #082753;
9	  background-clip: border-box;
10	  margin-bottom: 0;
11	  padding: 70px 5% 80px;
12	  position: relative;
13	}
14	
15	.container {
16	  width: 100%;
17	  max-width: 1280px;
18	  margin-left: auto;
19	  margin-right: auto;
20	}
21	
22	/* Badge */
23	.badgeRow {
24	  display: flex;
25	  justify-content: center;
26	  align-items: center;
27	  margin-bottom: 0;
28	}
29	
30	.badge {
31	  background-color: #21cfff12;
32	  border: 1px solid #05bafe;
33	  border-radius: 20px;
34	  margin-bottom: 0;
35	  padding: 0 13px;
36	  line-height: 14px;
37	  display: inline-flex;
38	  align-items: center;
39	}
40	
41	.badgeText {
42	  margin: 0;
43	  font-size: 12px;
44	  font-family: 'Roobert PRO', Arial, sans-serif;
45	  font-weight: 500;
46	  color: #21cfff;
47	  -webkit-text-fill-color: transparent;
48	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
49	  -webkit-background-clip: text;
50	  background-clip: text;
51	}
52	
53	/* Heading */
54	.heading {
55	  color: #fff;
56	  font-family: 'Roobert PRO', Arial, sans-serif;
57	  font-size: 40px;
58	  font-weight: 700;
59	  text-align: center;
60	  line-height: 48px;
61	  margin-top: 0;
62	  margin-bottom: 20px;
63	}
64	
65	/* Subtitle */
66	.subtitle {
67	  color: #fff;
68	  opacity: 0.8;
69	  font-size: 16px;
70	  line-height: 28px;
71	  text-align: center;
72	  margin-bottom: 0;
73	  font-family: 'Roobert PRO', Arial, sans-serif;
74	  max-width: 680px;
75	  margin-left: auto;
76	  margin-right: auto;
77	}
78	
79	/* Feature cards grid */
80	.featureGrid {
81	  display: grid;
82	  grid-column-gap: 20px;
83	  grid-row-gap: 20px;
84	  grid-template-rows: auto;
85	  grid-template-columns: 1fr 1fr 1fr;
86	  margin-top: 40px;
87	}
88	
89	.featureCard {
90	  grid-column-gap: 0;
91	  grid-row-gap: 0;
92	  text-align: center;
93	  background-color: #1c3861;
94	  border: 1px solid rgba(255, 255, 255, 0.11);
95	  border-radius: 20px;
96	  flex-flow: column;
97	  justify-content: space-between;
98	  align-items: center;
99	  padding: 25px 17px 17px;
100	  text-decoration: none;
101	  display: flex;
102	}
103	
104	.textWrapper {
105	  margin-bottom: 20px;
106	}
107	
108	.cardTitle {
109	  color: #fff;
110	  letter-spacing: -0.02em;
111	  margin-bottom: 10px;
112	  font-family: 'Roobert PRO', Arial, sans-serif;
113	  font-size: 20px;
114	  font-weight: 700;
115	  line-height: 25px;
116	}
117	
118	.cardDesc {
119	  color: #fff;
120	  opacity: 0.8;
121	  min-height: auto;
122	  font-family: 'Roobert PRO', Arial, sans-serif;
123	  font-size: 16px;
124	  letter-spacing: -0.08px;
125	  margin-bottom: 20px;
126	  line-height: 28px;
127	}
128	
129	.fullWidthImage {
130	  display: block;
131	  width: 100%;
132	  height: auto;
133	  border-radius: 8px;
134	}
135	
136	/* ============================================================
137	   max-width: 991px
138	   ============================================================ */
139	@media screen and (max-width: 991px) {
140	  .section {
141	    padding-top: 0;
142	    padding-bottom: 0;
143	  }
144	
145	  .heading {
146	    font-size: 35px;
147	    line-height: 45px;
148	  }
149	}
150	
151	/* ============================================================
152	   max-width: 767px
153	   ============================================================ */
154	@media screen and (max-width: 767px) {
155	  .section {
156	    padding: 50px 5% 60px;
157	    margin-top: 0;
158	  }
159	
160	  .featureGrid {
161	    grid-template-columns: 1fr;
162	    margin-top: 20px;
163	  }
164	
165	  .featureCard {
166	    padding-left: 18px;
167	    padding-right: 18px;
168	  }
169	
170	  .cardTitle {
171	    text-align: center;
172	  }
173	
174	  .cardDesc {
175	    text-align: center;
176	  }
177	
178	  .heading {
179	    font-size: 23px;
180	    line-height: 32px;
181	    margin-bottom: 10px;
182	    text-align: center;
183	  }
184	
185	  .subtitle {
186	    text-align: center;
187	  }
188	}
189	
190	/* ============================================================
191	   max-width: 479px  (mobile)
192	   ============================================================ */
193	@media screen and (max-width: 479px) {
194	  .featureGrid {
195	    grid-template-columns: 1fr;
196	  }
197	}
