1	/* ============================================================
2	   PROCESS STEPS — process-steps.module.css
3	   ============================================================ */
4	
5	.section {
6	  background-color: transparent;
7	  padding: 60px 5% 60px;
8	  position: relative;
9	  overflow: hidden;
10	}
11	
12	.container {
13	  width: 100%;
14	  max-width: 1280px;
15	  margin-left: auto;
16	  margin-right: auto;
17	}
18	
19	/* Header block */
20	.header {
21	  text-align: center;
22	  max-width: 720px;
23	  margin-left: auto;
24	  margin-right: auto;
25	  margin-bottom: 56px;
26	}
27	
28	.heading {
29	  color: #092245;
30	  font-family: 'Roobert PRO', Arial, sans-serif;
31	  font-size: 40px;
32	  font-weight: 700;
33	  line-height: 1.2;
34	  margin-bottom: 16px;
35	}
36	
37	.subtitle {
38	  color: #2b2b2b;
39	  font-family: 'Roobert PRO', Arial, sans-serif;
40	  font-size: 16px;
41	  font-weight: 400;
42	  line-height: 28px;
43	  margin-bottom: 24px;
44	}
45	
46	.demoLink {
47	  color: #fff;
48	  font-family: 'Roobert PRO', Arial, sans-serif;
49	  font-size: 1rem;
50	  font-weight: 700;
51	  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
52	  background-position: 93%, 0 0;
53	  background-repeat: no-repeat, repeat;
54	  background-size: auto, auto;
55	  border: 2px solid transparent;
56	  border-radius: 0.75rem;
57	  justify-content: center;
58	  align-items: center;
59	  padding: 0.75rem 3rem 0.75rem 1.25rem;
60	  line-height: 1.75rem;
61	  text-decoration: none;
62	  display: inline-flex;
63	  box-shadow: 0 0 5px #0000001a;
64	  transition: background-color 0.2s;
65	}
66	
67	.demoLink:hover {
68	  background-color: #092245;
69	  background-image: url('/images/webflow/Group-46729-2.svg');
70	  background-repeat: no-repeat;
71	  background-size: auto;
72	}
73	
74	/* Steps grid (.webdev-sec5-grid) */
75	.stepsGrid {
76	  display: grid;
77	  grid-column-gap: 0px;
78	  grid-row-gap: 0px;
79	  grid-template-rows: auto;
80	  grid-template-columns: 1fr 1fr 1fr 1fr;
81	  align-self: stretch;
82	}
83	
84	.step {
85	  flex-flow: column;
86	  justify-content: flex-start;
87	  align-items: flex-start;
88	  padding: 0 40px 0 0;
89	  display: flex;
90	  position: relative;
91	}
92	
93	/* Dashed connector line (.dashed-divider) */
94	.dashedDivider {
95	  z-index: 1;
96	  border-top: 1px dashed #082753;
97	  width: 100%;
98	  height: 2px;
99	  position: absolute;
100	  inset: 33px auto auto 0%;
101	}
102	
103	/* Number circle (.white-round + .sky-digit) */
104	.numberCircle {
105	  display: inline-flex;
106	  align-items: center;
107	  justify-content: center;
108	  width: 65px;
109	  height: 65px;
110	  border-radius: 50px;
111	  border: 1px dashed #082753;
112	  background-color: #fff;
113	  margin-bottom: 15px;
114	  position: relative;
115	  z-index: 3;
116	}
117	
118	.number {
119	  font-family: 'Roobert PRO', Arial, sans-serif;
120	  font-size: 22px;
121	  font-weight: 700;
122	  line-height: 1;
123	  background-image: linear-gradient(180deg, #21cfff, #019ae6);
124	  -webkit-background-clip: text;
125	  -webkit-text-fill-color: transparent;
126	  background-clip: text;
127	  text-align: center;
128	}
129	
130	.stepTitle {
131	  color: #082753;
132	  font-family: 'Roobert PRO', Arial, sans-serif;
133	  font-size: 18px;
134	  font-weight: 700;
135	  line-height: 25px;
136	  margin-bottom: 10px;
137	}
138	
139	.stepText {
140	  color: #2b2b2b;
141	  font-family: 'Roobert PRO', Arial, sans-serif;
142	  font-size: 1.125rem;
143	  font-weight: 400;
144	  line-height: 28px;
145	  margin: 0;
146	}
147	
148	/* ============================================================
149	   max-width: 991px
150	   ============================================================ */
151	@media screen and (max-width: 991px) {
152	  .section {
153	    padding-top: 50px;
154	    padding-bottom: 40px;
155	  }
156	
157	  .heading {
158	    font-size: 34px;
159	  }
160	
161	  .stepsGrid {
162	    grid-template-columns: 1fr 1fr;
163	    grid-column-gap: 40px;
164	    grid-row-gap: 40px;
165	  }
166	
167	  .dashedDivider {
168	    display: none;
169	  }
170	
171	  .step {
172	    padding-right: 0;
173	  }
174	}
175	
176	/* ============================================================
